"""Arithmetic expression evaluator (Approach A: recursive descent).

Grammar (one function per precedence level):

    expression := term (('+' | '-') term)*
    term       := unary (('*' | '/') unary)*
    unary      := '-' unary | power
    power      := primary ('^' unary)?          # right-associative
    primary    := NUMBER | IDENT | '(' expression ')'

Placing ``unary`` above ``power`` makes ``-2^2`` parse as ``-(2^2)``, while
letting the exponent's right operand be a ``unary`` allows ``2 ^ -1``.
"""

from __future__ import annotations

import re
from collections.abc import Mapping

__all__ = ["ExprError", "evaluate"]


class ExprError(Exception):
    """Raised for syntax errors, unknown variables, or division by zero."""


_TOKEN_RE = re.compile(
    r"""
    \s*(?:
        (?P<number>\d+\.\d*|\.\d+|\d+)
      | (?P<ident>[A-Za-z_][A-Za-z0-9_]*)
      | (?P<op>[-+*/^()])
    )
    """,
    re.VERBOSE,
)


def _tokenize(text: str) -> list[tuple[str, str]]:
    tokens: list[tuple[str, str]] = []
    pos = 0
    while pos < len(text):
        match = _TOKEN_RE.match(text, pos)
        if match is None:
            # Either an invalid character or only trailing whitespace remains.
            if text[pos:].strip() == "":
                break
            raise ExprError(f"unexpected character {text[pos:].lstrip()[0]!r} at position {pos}")
        kind = match.lastgroup
        tokens.append((kind, match.group(kind)))
        pos = match.end()
    tokens.append(("eof", ""))
    return tokens


class _Parser:
    def __init__(self, tokens: list[tuple[str, str]], variables: Mapping[str, float]):
        self._tokens = tokens
        self._pos = 0
        self._variables = variables

    # -- token helpers -----------------------------------------------------
    def _peek(self) -> tuple[str, str]:
        return self._tokens[self._pos]

    def _advance(self) -> tuple[str, str]:
        token = self._tokens[self._pos]
        self._pos += 1
        return token

    def _accept_op(self, *ops: str) -> str | None:
        kind, value = self._peek()
        if kind == "op" and value in ops:
            self._advance()
            return value
        return None

    def _expect_op(self, op: str) -> None:
        if self._accept_op(op) is None:
            kind, value = self._peek()
            found = "end of input" if kind == "eof" else repr(value)
            raise ExprError(f"expected {op!r} but found {found}")

    # -- grammar -----------------------------------------------------------
    def parse(self) -> float:
        value = self._expression()
        kind, found = self._peek()
        if kind != "eof":
            raise ExprError(f"unexpected token {found!r}")
        return value

    def _expression(self) -> float:
        value = self._term()
        while (op := self._accept_op("+", "-")) is not None:
            rhs = self._term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def _term(self) -> float:
        value = self._unary()
        while (op := self._accept_op("*", "/")) is not None:
            rhs = self._unary()
            if op == "*":
                value = value * rhs
            else:
                if rhs == 0:
                    raise ExprError("division by zero")
                value = value / rhs
        return value

    def _unary(self) -> float:
        if self._accept_op("-") is not None:
            return -self._unary()
        return self._power()

    def _power(self) -> float:
        base = self._primary()
        if self._accept_op("^") is not None:
            exponent = self._unary()  # right-associative; permits ``2 ^ -1``
            try:
                result = base ** exponent
            except ZeroDivisionError as exc:
                raise ExprError("division by zero") from exc
            except OverflowError as exc:
                raise ExprError("result too large") from exc
            if isinstance(result, complex):
                raise ExprError("result is not a real number")
            return result
        return base

    def _primary(self) -> float:
        kind, value = self._advance()
        if kind == "number":
            return float(value)
        if kind == "ident":
            try:
                return float(self._variables[value])
            except KeyError:
                raise ExprError(f"unknown variable {value!r}") from None
        if kind == "op" and value == "(":
            inner = self._expression()
            self._expect_op(")")
            return inner
        found = "end of input" if kind == "eof" else repr(value)
        raise ExprError(f"expected a number, variable or '(' but found {found}")


def evaluate(text: str, variables: Mapping[str, float] | None = None) -> float:
    """Evaluate an arithmetic expression and return the result as a float.

    Raises ExprError for syntax errors, unknown variables, or division by zero.
    """
    if not isinstance(text, str):
        raise ExprError("expression must be a string")
    return _Parser(_tokenize(text), variables or {}).parse()
